  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.3/codesynapse-darwin-arm64"
      sha256 "b2ddfaea3a76ac35e2db885575f816361db96144923d4efa40d63a9e644e0711"
    end
    on_intel do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.3/codesynapse-darwin-amd64"
      sha256 "4b5737c6a1ec21a67469dafdca642b37fb2a7f2633496e45e0ff39ff7f1f480c"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.3/codesynapse-linux-arm64"
      sha256 "417cb4ec6d62f280b5d27ab4843ae484f58597f49d734c617fc946576bb7780b"
    end
    on_intel do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.3/codesynapse-linux-amd64"
      sha256 "0713c783e55452fbeaea7677e9491f6929a937092cd550bf4a9eee017a46d50e"
    end
  end

  def install
    # A bare download isn't executable yet, and codesynapse runs below to
    # generate its completions.
    binary = Dir["codesynapse-*"].first
    chmod 0755, binary
    bin.install binary => "codesynapse"
    generate_completions_from_executable(bin/"codesynapse", "completion")
  end

  def caveats
    <<~EOS
      Connect Claude Code with a personal key (Settings → API keys in the dashboard):
        CODESYNAPSE_MCP_TOKEN=csk_... codesynapse mcp install --only claude
      then open a new chat. The bridge follows `brew upgrade codesynapse`.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/codesynapse --version")
    assert_match "__start_codesynapse", (bash_completion/"codesynapse").read
    # The bridge refuses to start without a chat ID instead of inventing one.
    assert_match "no chat session", shell_output("#{bin}/codesynapse mcp bridge 2>&1", 1)
  end
end
